const crypto = require('crypto');
const http = require('http');
const fs = require('fs');

const STATE_FILE = '/memory/project_rag_state.json';

function uuidv5(name) {
  const nsHex = '6ba7b8109dad11d180b400c04fd430c8';
  const nsBuf = Buffer.from(nsHex, 'hex');
  const nameBuf = Buffer.from(name, 'utf8');
  const hash = crypto.createHash('sha1').update(Buffer.concat([nsBuf, nameBuf])).digest();
  hash[6] = (hash[6] & 0x0f) | 0x50;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const h = hash.slice(0, 16).toString('hex');
  return h.slice(0,8) + '-' + h.slice(8,12) + '-' + h.slice(12,16) + '-' + h.slice(16,20) + '-' + h.slice(20,32);
}

function httpCall(method, host, port, urlPath, body) {
  return new Promise(function(resolve, reject) {
    const data = JSON.stringify(body);
    const req = http.request(
      { host: host, port: port, path: urlPath, method: method, headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      function(res) {
        let buf = '';
        res.on('data', function(c) { buf += c; });
        res.on('end', function() { try { resolve(JSON.parse(buf)); } catch(e) { resolve({}); } });
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  state = raw.files !== undefined ? raw : { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
} catch (e) {
  return [{ json: { status: 'no_state', processed: 0 } }];
}

const dirtyProjects = state.dirty_projects || [];
if (dirtyProjects.length === 0) {
  return [{ json: { status: 'nothing_to_do', processed: 0 } }];
}

const processed = [];
const failedProjects = [];

for (const project of dirtyProjects) {
  try {
    // Query all directory summaries for this project (level=directory, project=project)
    const scrollRes = await httpCall('POST', 'qdrant', 6333, '/collections/project_rag/points/scroll', {
      filter: {
        must: [
          { key: 'metadata.level', match: { value: 'directory' } },
          { key: 'metadata.project', match: { value: project } }
        ]
      },
      limit: 200,
      with_payload: true,
      with_vector: false
    });

    const points = (scrollRes.result && scrollRes.result.points) || [];

    // Also grab direct file summaries at project root (parent_id = project)
    const rootFileRes = await httpCall('POST', 'qdrant', 6333, '/collections/project_rag/points/scroll', {
      filter: {
        must: [
          { key: 'metadata.level', match: { value: 'file' } },
          { key: 'metadata.parent_id', match: { value: project } }
        ]
      },
      limit: 50,
      with_payload: true,
      with_vector: false
    });
    const rootFiles = (rootFileRes.result && rootFileRes.result.points) || [];

    if (points.length === 0 && rootFiles.length === 0) {
      // Nothing synthesized yet — keep dirty
      failedProjects.push(project);
      continue;
    }

    // Build summary input: top-level dirs first, then any root files
    const dirMetas = points.map(function(p) { return p.payload && p.payload.metadata ? p.payload.metadata : p.payload || {}; });
    // Sort top-level dirs (depth = 2 parts: project/dirname)
    const topDirs = dirMetas.filter(function(m) {
      return m.hierarchy_id && m.hierarchy_id.split('/').length === 2;
    });
    const deeperDirs = dirMetas.filter(function(m) {
      return m.hierarchy_id && m.hierarchy_id.split('/').length > 2;
    });
    const allSources = topDirs.concat(deeperDirs).slice(0, 20);

    const summaryLines = allSources.map(function(m) {
      const label = m.hierarchy_id || m.filename || '?';
      return label + ': ' + (m.purpose || m.summary || '');
    }).join('\n');

    const rootFileLines = rootFiles.map(function(p) {
      const m = p.payload && p.payload.metadata ? p.payload.metadata : p.payload || {};
      return (m.filename || '?') + ': ' + (m.purpose || m.summary || '');
    }).join('\n');

    const inputText = summaryLines + (rootFileLines ? '\n' + rootFileLines : '');

    const chatRes = await httpCall('POST', 'host.docker.internal', 11434, '/api/chat', {
      model: 'qwen2.5-coder:14b',
      messages: [
        { role: 'system', content: 'You write project overviews for a semantic search index. Given a list of directories and files with their purposes, synthesize a concise project summary. Output STRICT JSON only, no markdown fences.' },
        { role: 'user', content: 'Project: ' + project + '\nComponents:\n' + inputText + '\n\nRespond with STRICT JSON: {"summary": "<2-3 sentences describing what this project does and who it is for>", "purpose": "<short phrase>", "subsystems": ["<component name: brief description>"], "tech_stack": ["<technology>"], "topics": ["<keyword>"]}' }
      ],
      stream: false,
      options: { temperature: 0.1, num_predict: 500 }
    });

    let parsed = {};
    try {
      const rawText = (chatRes.message && chatRes.message.content) || '';
      parsed = JSON.parse(rawText.replace(/```json|```/g, '').trim());
    } catch (e) {
      parsed = {
        summary: 'Project ' + project + ' with ' + allSources.length + ' components',
        purpose: project,
        subsystems: [],
        tech_stack: [],
        topics: []
      };
    }

    // Embed
    const embedText = [
      'Project: ' + project,
      'Purpose: ' + (parsed.purpose || parsed.summary || ''),
      parsed.subsystems && parsed.subsystems.length ? 'Subsystems: ' + parsed.subsystems.join(', ') : '',
      parsed.tech_stack && parsed.tech_stack.length ? 'Tech stack: ' + parsed.tech_stack.join(', ') : '',
      parsed.topics && parsed.topics.length ? 'Topics: ' + parsed.topics.join(', ') : ''
    ].filter(Boolean).join('\n');

    const embedRes = await httpCall('POST', 'host.docker.internal', 11434, '/api/embed', {
      model: 'qwen3-embedding:4b', input: embedText
    });
    const vector = (embedRes.embeddings || [[]])[0];

    if (!vector || !vector.length) {
      const line = new Date().toISOString() + '\tproject_embed_empty\t' + project + '\n';
      try { fs.appendFileSync('/memory/project_rag_failures.log', line); } catch (err) {}
      failedProjects.push(project);
      continue;
    }

    const contentText = [
      parsed.summary || '',
      parsed.subsystems && parsed.subsystems.length ? 'Subsystems: ' + parsed.subsystems.join(' | ') : '',
      parsed.tech_stack && parsed.tech_stack.length ? 'Tech: ' + parsed.tech_stack.join(', ') : '',
      parsed.topics && parsed.topics.length ? 'Topics: ' + parsed.topics.join(', ') : ''
    ].filter(Boolean).join('\n');

    const pointId = uuidv5('project:' + project);
    await httpCall('PUT', 'qdrant', 6333, '/collections/project_rag/points?wait=false', {
      points: [{
        id: pointId,
        vector: vector,
        payload: {
          content: contentText,
          metadata: {
            hierarchy_id: project,
            level: 'project',
            parent_id: null,
            project: project,
            summary: parsed.summary || '',
            purpose: parsed.purpose || '',
            subsystems: parsed.subsystems || [],
            tech_stack: parsed.tech_stack || [],
            topics: parsed.topics || [],
            children: topDirs.map(function(m) { return m.hierarchy_id; }).filter(Boolean),
            updated_at: new Date().toISOString()
          }
        }
      }]
    });

    processed.push(project);
  } catch (e) {
    const line = new Date().toISOString() + '\tproject_synthesis_error\t' + project + '\t' + String(e) + '\n';
    try { fs.appendFileSync('/memory/project_rag_failures.log', line); } catch (err) {}
    failedProjects.push(project);
  }
}

state.dirty_projects = failedProjects;
fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

return [{ json: { status: 'done', processed: processed.length, failed: failedProjects.length } }];
